---Handle to the running application (Rust: `tauri::AppHandle`).
---@class mare.App
local App = {}

---Send an event to every window. Frontend: `listen("name", cb)`.
---@param event string
---@param payload? mare.Json
function App:emit(event, payload) end

---Send an event to one window only.
---@param label string Window label.
---@param event string
---@param payload? mare.Json
function App:emit_to(label, event, payload) end

---Listen for an event. The callback receives the decoded payload.
---@param event string
---@param callback fun(payload: any)
---@return integer id Pass to `app:unlisten()`.
function App:listen(event, callback) end

---Like `listen`, but runs at most once.
---@param event string
---@param callback fun(payload: any)
---@return integer id
function App:once(event, callback) end

---@param id integer
function App:unlisten(id) end

---Quit the app.
---@param code? integer Default 0.
function App:exit(code) end

---Restart the app.
function App:restart() end

---Run JavaScript in a window's webview.
---@param label string
---@param js string
function App:eval_in(label, js) end

---@param label string
---@return mare.Window?
function App:get_webview_window(label) end

---Labels of all open windows.
---@return string[]
function App:windows() end

---Create a new window. See `tauri.window.new` for options.
---@param label string
---@param opts? mare.WindowOptions
---@return mare.Window
function App:create_window(label, opts) end

---@return mare.Paths
function App:path() end

---@return mare.PackageInfo
function App:package_info() end

---Set the application menu bar (see `tauri.menu.new`).
---@param menu mare.Menu
function App:set_menu(menu) end

---Called when any menu item is clicked.
---@param callback fun(event: { id: string })
function App:on_menu_event(callback) end

