---@class mare.Tauri
tauri = {}

---Register a command the frontend can call with `invoke(name, args)`.
---Return a value to resolve the promise, or call `error()` to reject it.
---@param name string
---@param handler fun(ctx: mare.CommandContext, args: any): mare.Json
function tauri.command(name, handler) end

---Run once at startup (Rust: `Builder::setup`).
---@param callback fun(app: mare.App)
function tauri.setup(callback) end

---Handle app lifecycle events. Return `false` for `exit_requested` to keep the app running.
---@param callback fun(event: mare.RunEvent): boolean?
function tauri.on_run_event(callback) end

---Serve a custom URI scheme from Lua. Also list the scheme under "protocols" in mare.json.
---@param scheme string
---@param handler fun(ctx: { scheme: string }, request: mare.ProtocolRequest): mare.ProtocolResponse
function tauri.register_protocol(scheme, handler) end

---Pause the current coroutine without freezing the app.
---@param seconds number
function tauri.sleep(seconds) end

---Run a function in the background.
---@param fn fun()
function tauri.spawn(fn) end

---Keep a value for the life of the app (Rust: `Builder::manage`). Read it with `ctx.state(name)`.
---@param name string
---@param value any
function tauri.manage(name, value) end

---@param name string
---@return any
function tauri.state(name) end

